svg.script:
var svgNS = "http://www.w3.org/2000/svg";
var tooltip, tooltip_bg;

function init(evt) {
    if ( window.svgDocument == null ) {
        svgDocument = evt.target.ownerDocument;
        svgHeight = parseInt(svgDocument.documentElement.getAttribute("height"));
        svgWidth = parseInt(svgDocument.documentElement.getAttribute("width"));
    }
    tooltip = svgDocument.getElementById('tooltip');
    tooltip_bg = svgDocument.getElementById('tooltip_bg');
} 

function ShowTooltip(evt, txt) {

        /* Clean toolip content */
        while (tooltip.lastChild) {
            tooltip.removeChild(tooltip.lastChild)
        }
        var bgX_offset = 10;
        var bgY_offset = 10;
        var ttX_offset = 8;
        var ttY_offset = 14;
        var tooltip_x;
        var tooltip_y;
        var bg_x;
        var bg_y;
        height = 17;

        curr_x = evt.pageX;
        curr_y = evt.pageY;

        bg_x = curr_x + bgX_offset;
        tooltip_x = bg_x + ttX_offset;
        if (curr_y > svgHeight / 2) {
            bg_y = curr_y - (bgY_offset + height);
        } else {
            bg_y = curr_y + bgY_offset;
        }
        tooltip_y = bg_y + ttY_offset;
        /* Populate tooltip with tspan elements and get longest of them */
        var shift_y = 0;
        var tspan_element = document.createElementNS(svgNS, "tspan");
        tspan_element.setAttributeNS(null, "dy", shift_y);
        tspan_element.setAttributeNS(null, "x", tooltip_x);
        var text_node = svgDocument.createTextNode(txt);
        tspan_element.appendChild(text_node);
        tooltip.appendChild(tspan_element);
        var length = tspan_element.getComputedTextLength();

        /* add right margin to tooltip */
        length = Math.ceil(length + 15);
        right_bgX = bg_x + length;
        console.log("length", length, "bgx", bg_x, "right_bgX", right_bgX);
        if (right_bgX > svgWidth) {
            bg_x = bg_x - (right_bgX - svgWidth + 1);
        }
        if (bg_x < 1) {
            bg_x = 1;
        }
        tooltip_x = bg_x + ttX_offset;
        tooltip_bg.setAttributeNS(null,"width",length);
        tooltip_bg.setAttributeNS(null,"height",height);
        tooltip_bg.setAttributeNS(null,"x", bg_x);
        tooltip_bg.setAttributeNS(null,"y", bg_y);
        tooltip_bg.setAttributeNS(null,"visibility","visible");
        tooltip.setAttributeNS(null,"x", tooltip_x);
        tooltip.setAttributeNS(null,"y", tooltip_y);
        tooltip.setAttributeNS(null,"visibility","visible");
        tspan_element.setAttributeNS(null, "x", tooltip_x);
}
function HideTooltip() {
  tooltip.setAttributeNS(null,"visibility","hidden");
  tooltip_bg.setAttributeNS(null,"visibility","hidden");
}
